import math

class Statistics3:
    MIN_SIZE_FOR_STD_DEV = 2

    @staticmethod
    def median(data):
        sorted_data = sorted(data)
        n = len(sorted_data)
        if n % 2 == 1:
            return sorted_data[n // 2]
        else:
            return (sorted_data[n // 2 - 1] + sorted_data[n // 2]) / 2

    @staticmethod
    def mode(data):
        counts = {}
        for value in data:
            counts[value] = counts.get(value, 0) + 1
        max_count = max(counts.values())
        mode_values = [value for value, count in counts.items() if count == max_count]
        return mode_values

    @staticmethod
    def correlation(x, y):
        n = len(x)
        mean_x = sum(x) / n
        mean_y = sum(y) / n
        numerator = sum((xi - mean_x) * (yi - mean_y) for xi, yi in zip(x, y))
        denominator = math.sqrt(sum((xi - mean_x) ** 2 for xi in x) * sum((yi - mean_y) ** 2 for yi in y))
        if denominator == 0:
            return None
        return numerator / denominator

    @staticmethod
    def mean(data):
        if len(data) == 0:
            return None
        return sum(data) / len(data)

    @staticmethod
    def _extract_column(data, index):
        return [row[index] for row in data]

    @staticmethod
    def correlation_matrix(data):
        matrix = []
        num_columns = len(data[0])
        for i in range(num_columns):
            row_values = []
            column_i = Statistics3._extract_column(data, i)
            for j in range(num_columns):
                column_j = Statistics3._extract_column(data, j)
                correlation = Statistics3.correlation(column_i, column_j)
                row_values.append(correlation)
            matrix.append(row_values)
        return matrix

    @staticmethod
    def standard_deviation(data):
        n = len(data)
        if n < Statistics3.MIN_SIZE_FOR_STD_DEV:
            return None
        mean_value = Statistics3.mean(data)
        variance = sum((x - mean_value) ** 2 for x in data) / (n - 1)
        return math.sqrt(variance)

    @staticmethod
    def z_score(data):
        mean = Statistics3.mean(data)
        std_deviation = Statistics3.standard_deviation(data)
        if std_deviation is None or std_deviation == 0:
            return None
        return [(x - mean) / std_deviation for x in data]
